vertex.#include <common>:
#include <common>
attribute float erde;
varying float vErde;
varying vec2 vWelt;

fragment.#include <common>:
#include <common>
uniform sampler2D tGras;
uniform sampler2D tErde;
uniform sampler2D tGross;
varying float vErde;
varying vec2 vWelt;

fragment.#include <map_fragment>:
vec3 gT = texture2D(tGras, vWelt * 0.29).rgb, eT = texture2D(tErde, vWelt * 0.25).rgb;
float gross = texture2D(tGross, vWelt * 0.021).r * 0.6 + texture2D(tGross, vWelt * 0.0071 + 0.3).r * 0.4;
diffuseColor.rgb *= mix(gT, eT, smoothstep(0.15, 0.85, vErde)) * (0.8 + 0.75 * gross) * 1.25;
